/**
 * The Waldstatt's waters, one page of 10 × 10 km per file (ADR 0002): the
 * rivers, lakes and border of that square, generated by the Waldstatt's
 * tools/waters.mjs from swisstopo data. The game loads a page when it first
 * comes into view; the service worker keeps it for offline starts.
 */
import type { APIRoute, GetStaticPaths } from "astro";
// Read as text: typing the generated data would only slow the checks down.
import source from "../../waldstatt/data/water-pages.json?raw";

const pages: Record<string, unknown> = JSON.parse(source);

export const getStaticPaths: GetStaticPaths = () =>
  Object.keys(pages).map((key) => ({
    params: { page: key.replace(",", "_") },
    props: { key },
  }));

export const GET: APIRoute = ({ props }) =>
  new Response(JSON.stringify(pages[props.key as string]), {
    headers: { "Content-Type": "application/json" },
  });
